import { createTranslator } from 'next-intl';
import { describe, expect, it } from 'vitest';

import en from '@/lib/i18n/en.json';
import zh from '@/lib/i18n/zh.json';
import { mergeMessages } from '@/lib/i18n/merge-messages';
import {
  formatAbilityScore,
  formatSignedDelta,
  latestGradingMessageId,
  latestPoint,
  showsWindow,
  sparklinePath,
  trendLabel,
} from '@/lib/english-tutor/ability-view';
import { dimensionLabel } from '@/lib/english-tutor/dimension-label';
import type { EnglishAbility } from '@/types/english-ability';

// Generated by backend `compute_ability` (KAZI-1067) — ⛔ not a hand-written shape.
import fixture from './__fixtures__/kazi1067_ability_response.json';

const populated = fixture.populated as unknown as EnglishAbility;
const declining = fixture.declining as unknown as EnglishAbility;
const empty = fixture.empty as unknown as EnglishAbility;

// Real library + real messages (KAZI-1069 comment 13669 ②), merged the way the app does.
const zhMessages = mergeMessages(en, zh) as typeof en;
const tZh = createTranslator({ locale: 'zh', messages: zhMessages, namespace: 'english.envelope' });
const tEn = createTranslator({ locale: 'en', messages: en, namespace: 'english.envelope' });

describe('the fixture is the backend shape', () => {
  it('carries the §5.5.6 keys and nothing internal', () => {
    expect(Object.keys(populated).sort()).toEqual(
      ['modalities', 'overall', 'resolved_tags', 'scale', 'scale_version', 'updated_at'].sort()
    );
    expect(JSON.stringify(fixture)).not.toMatch(/grader|confidence/);
    expect(populated.scale).toBe('0-6');
  });
});

describe('scores (AC-P1: 0–6, two decimals)', () => {
  it('formats every number with two decimals', () => {
    expect(formatAbilityScore(4)).toBe('4.00');
    expect(formatAbilityScore(populated.overall)).toBe('3.94');
    expect(formatAbilityScore(null)).toBe('—');
  });
});

describe('trend copy uses t.has, not defaultValue (13669 ①)', () => {
  it('localises the backend trend values with the real translator', () => {
    expect(trendLabel(tZh, populated.modalities.writing?.trend)).toBe('上升');
    expect(trendLabel(tZh, declining.modalities.writing?.trend)).toBe('下降');
    expect(trendLabel(tEn, 'stable')).toBe('Stable');
  });

  it('returns null for an unknown value instead of the key path', () => {
    expect(trendLabel(tZh, 'plateau')).toBeNull();
    expect(trendLabel(tZh, null)).toBeNull();
  });
});

describe('window wording and sign (13697)', () => {
  it('says earlier-half → recent-half averages, signed from the value', () => {
    const w = populated.modalities.writing!.window;
    const text = tZh('progressWindowRange', {
      from: formatAbilityScore(w.from),
      to: formatAbilityScore(w.to),
      delta: formatSignedDelta(w.delta),
    });
    expect(text).toBe('前期均值 3.33 → 近期均值 3.89（+0.56）');
  });

  it('never renders "+-" for a negative delta', () => {
    const w = declining.modalities.writing!.window;
    expect(w.delta).toBeLessThan(0);
    const text = tZh('progressWindowRange', {
      from: formatAbilityScore(w.from),
      to: formatAbilityScore(w.to),
      delta: formatSignedDelta(w.delta),
    });
    expect(text).toBe('前期均值 4.50 → 近期均值 3.67（−0.83）');
    expect(text).not.toContain('+-');
    expect(formatSignedDelta(0)).toBe('0.00');
  });

  it('every locale template takes the sign from {delta}', () => {
    expect(en.english.envelope.progressWindowRange).not.toMatch(/\+\{delta\}/);
    expect(zh.english.envelope.progressWindowRange).not.toMatch(/\+\{delta\}/);
  });
});

describe('latest score comes from points, not window.to (13697 ③)', () => {
  it('differs from the later-half mean on the real shape', () => {
    const writing = populated.modalities.writing!;
    expect(latestPoint(writing)?.score).toBe(4.33);
    expect(writing.window.to).toBe(3.89);
  });
});

describe('the window line starts at three attempts (#230 review · Owen 2026-10-13)', () => {
  const two = fixture.two as unknown as EnglishAbility;

  it('shows for five, hides for one', () => {
    expect(showsWindow(populated.modalities.writing)).toBe(true);
    expect(showsWindow(populated.modalities.speaking)).toBe(false);
  });

  it('hides for two — the backend calls two attempts `stable` by rule', () => {
    const writing = two.modalities.writing!;
    expect(writing.window.n).toBe(2);
    expect(writing.trend).toBe('stable');
    expect(writing.window.delta).toBeGreaterThan(1); // the contradiction this hides
    expect(showsWindow(writing)).toBe(false);
  });
});

describe('dimension labels on the real shape', () => {
  it('localises every id the backend sends', () => {
    const dims = populated.modalities.writing!.dimensions;
    expect(dims.length).toBe(4);
    for (const d of dims) {
      const label = dimensionLabel(tZh, { key: d.id, label: d.label });
      expect(label).not.toMatch(/^english\./);
      expect(label).not.toBe(d.label);
    }
  });
});

describe('cold start (AC-P3)', () => {
  it('is all-null', () => {
    expect(empty.overall).toBeNull();
    expect(empty.modalities.writing).toBeNull();
    expect(empty.modalities.speaking).toBeNull();
  });
});

describe('refresh trigger', () => {
  const graded = (id: string, event: string) => ({ id, role: 'assistant', assistantMeta: { event } });

  it('keys on the newest graded assistant turn', () => {
    expect(
      latestGradingMessageId([
        graded('a1', 'writing_review'),
        { id: 'u1', role: 'user' },
        graded('a2', 'writing_prompt'),
      ])
    ).toBe('msg:a1');
    expect(
      latestGradingMessageId([graded('a1', 'writing_review'), graded('a3', 'speaking_feedback')])
    ).toBe('msg:a3');
    expect(latestGradingMessageId([graded('a4', 'writing_revise_review')])).toBe('msg:a4');
    expect(latestGradingMessageId([{ id: 'u', role: 'user' }])).toBeNull();
  });
});

describe('sparkline', () => {
  it('maps 0–6 onto the box, top = 6', () => {
    const pts = sparklinePath(
      [{ at: null, score: 0 }, { at: null, score: 6 }, { at: null, score: null }],
      { width: 100, height: 40 }
    );
    expect(pts).toEqual([
      { x: 0, y: 40, score: 0 },
      { x: 100, y: 0, score: 6 },
    ]);
  });
});

// KAZI-1069 write-back 13720 (FAIL「展开时判分刷新」): after a send the live reply is
// replaced by its history row, whose meta keeps only `form` / `grade_id`
// (backend `chat_persistence.PERSISTED_SURFACE_META_KEYS`) — `event` is gone.
describe('refresh key survives the history swap (13720)', () => {
  const before = [
    { id: '101', role: 'assistant', assistantMeta: { grade_id: 'g1', form: { kind: 'writing_revision' } } },
  ];
  const live = [
    ...before,
    { id: 'u2', role: 'user' },
    {
      id: 'assistant_1760364819000',
      role: 'assistant',
      assistantMeta: { event: 'writing_review', grade_id: 'g2', form: { kind: 'writing_revision' } },
    },
  ];
  const afterHistory = [
    ...before,
    { id: 'u2', role: 'user' },
    { id: '103', role: 'assistant', assistantMeta: { grade_id: 'g2', form: { kind: 'writing_revision' } } },
  ];

  it('changes on the new grade and stays changed once history replaces the live row', () => {
    const k0 = latestGradingMessageId(before);
    const k1 = latestGradingMessageId(live);
    const k2 = latestGradingMessageId(afterHistory);
    expect(k1).not.toBe(k0);
    expect(k2).toBe(k1);
  });

  it('a later non-graded turn that repeats the same grade_id does not refetch', () => {
    const followUp = [
      ...afterHistory,
      { id: 'u3', role: 'user' },
      { id: '105', role: 'assistant', assistantMeta: { event: 'review_followup', grade_id: 'g2' } },
    ];
    expect(latestGradingMessageId(followUp)).toBe(latestGradingMessageId(afterHistory));
  });
});
